cd /workspace/nox/web/site
python3 - <<'P'
import re,time
t=str(int(time.time()))
s=open('atlas.html',encoding='utf-8').read(); m=open('atlas-s1.main.html',encoding='utf-8').read()
s=re.sub(r'<main.*?</main>',lambda x:m,s,count=1,flags=re.S); open('atlas.html','w',encoding='utf-8').write(s)
for p in ['atlas','voice','index','chat']:
    fn=p+'.html'; s=open(fn,encoding='utf-8').read()
    for f in ['nox-atlas-s1.js','nox-sl-s1.js','nox-sl-s1.css']:
        s=re.sub(f.replace('.','\\.')+r'\?v=[0-9]*',f+'?v='+t,s)
    open(fn,'w',encoding='utf-8').write(s)
print('w4 ok')
P
